  for (const cell of [...liveCells, ...liveCells.flatMap(neighborsOf)]) {
    byKey.set(keyOf(cell), cell);
  }
  return [...byKey.values()];
};

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const live: LiveSet = new Set(liveCells.map(keyOf));
